class Solution {
  public String nextPalindrome(String num) {
    int n = num.length();
    char[] half = num.substring(0, n / 2).toCharArray();
    // the next palindrome comes from the next permutation of the first half
    int i = half.length - 2;
    while (i >= 0 && half[i] >= half[i + 1]) i--;
    if (i < 0) return "";
    int j = half.length - 1;
    while (half[j] <= half[i]) j--;
    char t = half[i];
    half[i] = half[j];
    half[j] = t;
    for (int l = i + 1, r = half.length - 1; l < r; l++, r--) {
      t = half[l];
      half[l] = half[r];
      half[r] = t;
    }
    String left = new String(half);
    return left + (n % 2 == 1 ? String.valueOf(num.charAt(n / 2)) : "") + new StringBuilder(left).reverse();
  }
}
